coding.referenceSolution:
type Sort = { field: string; dir: 'asc' | 'desc' };

function parseSort(param: string | null, allowed: string[]): Sort[] {
  if (!param) return [];
  const out: Sort[] = [];
  for (const raw of param.split(',')) {
    const part = raw.trim();
    if (!part) continue;
    const desc = part.startsWith('-');
    const field = desc ? part.slice(1) : part;
    if (allowed.includes(field)) out.push({ field, dir: desc ? 'desc' : 'asc' });
  }
  return out;
}

