const OPS = ['eq', 'ne', 'gt', 'gte', 'lt', 'lte'];

function parseFilters(query, allowed) {
  const filters = [];
  const errors = [];
  for (const [key, raw] of Object.entries(query)) {
    const m = key.match(/^(\w+)(?:\[(\w+)\])?$/);
    const field = m ? m[1] : key;
    const op = m && m[2] ? m[2] : 'eq';
    if (!allowed.includes(field)) {
      errors.push('unknown field: ' + field);
      continue;
    }
    if (!OPS.includes(op)) {
      errors.push('unknown operator: ' + op);
      continue;
    }
    const value = raw !== '' && !Number.isNaN(Number(raw)) ? Number(raw) : raw;
    filters.push({ field, op, value });
  }
  return { filters, errors };
}

