function validatePatch(body, allowed, readOnly) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return { status: 400, errors: ['body must be an object'] };
  }
  const keys = Object.keys(body);
  if (!keys.length) return { status: 400, errors: ['no fields to update'] };
  const errors = [];
  for (const k of keys) {
    if (readOnly.includes(k)) errors.push(k + ' is read-only');
    else if (!allowed.includes(k)) errors.push(k + ' is not allowed');
  }
  if (errors.length) return { status: 400, errors };
  return { status: 200, update: body };
}

