function processRequests(requests) {
  const seen = new Map();
  let next = 1;
  return requests.map(({ key, body }) => {
    const fingerprint = JSON.stringify(body);
    if (key && seen.has(key)) {
      const stored = seen.get(key);
      if (stored.fingerprint !== fingerprint) return { status: 422, error: 'key reused' };
      return { ...stored.res, replayed: true };
    }
    const res = { status: 201, orderId: next++, replayed: false };
    if (key) seen.set(key, { fingerprint, res });
    return res;
  });
}

