function pickFields(obj: Record<string, any>, fields: string | null): Record<string, any> {
  if (!fields) return obj;
  const out: Record<string, any> = {};
  for (const raw of fields.split(',')) {
    const path = raw.trim().split('.').filter(Boolean);
    if (!path.length) continue;
    let src: any = obj;
    let ok = true;
    for (const key of path) {
      if (src && typeof src === 'object' && key in src) src = src[key];
      else { ok = false; break; }
    }
    if (!ok) continue;
    let dst = out;
    for (const key of path.slice(0, -1)) dst = dst[key] ??= {};
    dst[path[path.length - 1]] = src;
  }
  return out;
}

