coding.referenceSolution:
function idempotency(events) {
  const keys = new Map();
  const out = [];
  for (const [type, key, value] of events) {
    if (type === 'finish') {
      const entry = keys.get(key);
      if (entry) entry.status = value;
      continue;
    }
    const entry = keys.get(key);
    if (!entry) {
      keys.set(key, { hash: value, status: null });
      out.push('process');
    } else if (entry.hash !== value) out.push('mismatch');
    else if (entry.status === null) out.push('conflict');
    else out.push('replay:' + entry.status);
  }
  return out;
}

