function versionLifecycle(version, policy, today) {
  const p = policy[version];
  if (!p) return { status: 404 };
  const headers = {};
  if (p.deprecated && today >= p.deprecated) {
    headers.Deprecation = '@' + Date.parse(p.deprecated) / 1000;
    if (p.sunset) headers.Sunset = new Date(p.sunset).toUTCString();
  }
  return { status: 200, headers };
}

