function applyPatch(doc, ops) {
  for (let i = 0; i < ops.length; i++) {
    const { op, path, value } = ops[i];
    const keys = path.split('/').slice(1);
    const last = keys.pop();
    let parent = doc;
    for (const k of keys) parent = parent && parent[k];
    if (!parent || typeof parent !== 'object') return { ok: false, failedOp: i, doc };
    if (op === 'test' && JSON.stringify(parent[last]) !== JSON.stringify(value)) return { ok: false, failedOp: i, doc };
    if ((op === 'replace' || op === 'remove') && !(last in parent)) return { ok: false, failedOp: i, doc };
    if (op === 'add' || op === 'replace') parent[last] = value;
    if (op === 'remove') delete parent[last];
  }
  return { ok: true, doc };
}

